class Solution:
    def maximumPopulation(self, logs: List[List[int]]) -> int:
        best = ans = 0
        for year in range(1950, 2051):
            cnt = sum(b <= year < d for b, d in logs)
            if cnt > best:
                best = cnt
                ans = year
        return ans

