class Solution {
public:
    int maximumPopulation(vector<vector<int>>& logs) {
        int best = 0, ans = 1950;
        for (int year = 1950; year <= 2050; ++year) {
            int cnt = 0;
            for (auto& p : logs)
                if (p[0] <= year && year < p[1]) ++cnt;
            if (cnt > best) { best = cnt; ans = year; }
        }
        return ans;
    }
};

